CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, tasks TEXT NOT NULL, created INTEGER NOT NULL, result TEXT, processing INTEGER NOT NULL DEFAULT 0, answer_hash TEXT);
CREATE TABLE IF NOT EXISTS callers(id TEXT PRIMARY KEY, minute INTEGER NOT NULL, calls INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS budget(id INTEGER PRIMARY KEY, spent REAL NOT NULL DEFAULT 0, reserved REAL NOT NULL DEFAULT 0, ceiling REAL NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO budget(id,spent,reserved,ceiling) VALUES(1,0,0,0);
